const aiResponse =
  $json.output ||
  $json.text ||
  $json.response ||
  '';

const mermaidRegex = /```mermaid\s*([\s\S]*?)```/gi;

const diagrams = [];
let match;

while ((match = mermaidRegex.exec(aiResponse)) !== null) {
  diagrams.push(match[1].trim());
}

function createDrawioUrl(mermaid, title) {
  if (!mermaid) return '';

  const payload = {
    type: 'mermaid',
    data: mermaid
  };

  return 'https://app.diagrams.net/?grid=1&pv=0&title=' +
    encodeURIComponent(title) +
    '#create=' +
    encodeURIComponent(JSON.stringify(payload));
}

const currentStateMermaid = diagrams[0] || '';
const improvedStateMermaid = diagrams[1] || '';

const currentUrl = createDrawioUrl(
  currentStateMermaid,
  'AS-IS Process'
);

const improvedUrl = createDrawioUrl(
  improvedStateMermaid,
  'TO-BE Process'
);

// Keep the original AI analysis and add clickable links
let finalResponse = aiResponse;

if (currentUrl || improvedUrl) {
  finalResponse += '\n\n---\n\n## Process Flow Diagrams\n\n';

  if (currentUrl) {
    finalResponse +=
      `### AS-IS Process\n[Open AS-IS Process in draw.io](${currentUrl})\n\n`;
  }

  if (improvedUrl) {
    finalResponse +=
      `### TO-BE Process\n[Open TO-BE Process in draw.io](${improvedUrl})\n`;
  }
} else {
  finalResponse +=
    '\n\n⚠️ No Mermaid diagram was detected in the AI response.';
}

return {
  json: {
    output: finalResponse,
    currentStateMermaid,
    improvedStateMermaid,
    currentStateDrawioUrl: currentUrl,
    improvedStateDrawioUrl: improvedUrl
  }
};

const item = $input.first();

// Get both PNG diagrams from the Merge node
const asIsBuffer = await this.helpers.getBinaryDataBuffer(0, 'asIsDiagram');
const toBeBuffer = await this.helpers.getBinaryDataBuffer(0, 'toBeDiagram');

const asIsBase64 = asIsBuffer.toString('base64');
const toBeBase64 = toBeBuffer.toString('base64');

// Get the original AI report
let reportContent =
  $('Create Draw.io Link').first().json.output || '';

// Get report name passed from the parent workflow
let reportName =
  $('Prepare Report Handoff').first().json.reportName ||
  'Process Improvement Report';

// Remove routing marker
reportContent = reportContent
  .replace(/PROCESS_FLOW_READY:\s*(true|false)/gi, '')
  .trim();

function escapeHtml(text) {
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function inlineFormat(text) {
  return escapeHtml(text)
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.+?)\*/g, '<em>$1</em>');
}

function splitCells(line) {
  return line
    .trim()
    .replace(/^\|/, '')
    .replace(/\|$/, '')
    .split('|')
    .map(v => v.trim());
}

function isTableSeparator(line) {
  return /^\s*\|?(\s*:?-+:?\s*\|)+\s*:?-+:?\s*\|?\s*$/.test(line);
}

function markdownToHtml(markdown) {
  const lines = markdown.split(/\r?\n/);

  let html = '';
  let inMermaid = false;
  let inUL = false;
  let inOL = false;
  let asIsInserted = false;
  let toBeInserted = false;

  function closeLists() {
    if (inUL) {
      html += '</ul>';
      inUL = false;
    }
    if (inOL) {
      html += '</ol>';
      inOL = false;
    }
  }

  for (let i = 0; i < lines.length; i++) {
    const raw = lines[i];
    const line = raw.trim();

    // Remove Mermaid source code from Word;
    // actual rendered PNG will be inserted instead
    if (/^```mermaid/i.test(line)) {
      inMermaid = true;
      continue;
    }

    if (inMermaid) {
      if (line === '```') {
        inMermaid = false;
      }
      continue;
    }

    if (/^PROCESS_FLOW_READY:/i.test(line)) {
      continue;
    }

    // Markdown heading
    const heading = raw.match(/^(#{1,6})\s+(.+)$/);

    if (heading) {
      closeLists();

      const level = Math.min(heading[1].length, 4);
      const title = heading[2].trim();

      html += `<h${level}>${inlineFormat(title)}</h${level}>`;

      // Insert AS-IS diagram underneath its heading
      if (
        /AS[- ]IS.*PROCESS FLOW/i.test(title) &&
        !asIsInserted
      ) {
        html += `
          <div class="diagram">
            <img src="data:image/png;base64,${asIsBase64}" />
            <div class="caption">AS-IS Process Flow</div>
          </div>
        `;
        asIsInserted = true;
      }

      // Insert TO-BE diagram underneath its heading
      if (
        /TO[- ]BE.*PROCESS FLOW/i.test(title) &&
        !toBeInserted
      ) {
        html += `
          <div class="diagram">
            <img src="data:image/png;base64,${toBeBase64}" />
            <div class="caption">TO-BE Process Flow</div>
          </div>
        `;
        toBeInserted = true;
      }

      continue;
    }

    // Markdown tables
    if (
      raw.includes('|') &&
      i + 1 < lines.length &&
      isTableSeparator(lines[i + 1])
    ) {
      closeLists();

      const headers = splitCells(raw);

      html += '<table><thead><tr>';

      for (const header of headers) {
        html += `<th>${inlineFormat(header)}</th>`;
      }

      html += '</tr></thead><tbody>';

      i += 2;

      while (i < lines.length && lines[i].includes('|')) {
        const cells = splitCells(lines[i]);

        html += '<tr>';

        for (const cell of cells) {
          html += `<td>${inlineFormat(cell)}</td>`;
        }

        html += '</tr>';
        i++;
      }

      i--;
      html += '</tbody></table>';
      continue;
    }

    // Bullet list
    if (/^[-*]\s+/.test(line)) {
      if (inOL) {
        html += '</ol>';
        inOL = false;
      }

      if (!inUL) {
        html += '<ul>';
        inUL = true;
      }

      html += `<li>${inlineFormat(
        line.replace(/^[-*]\s+/, '')
      )}</li>`;

      continue;
    }

    // Numbered list
    if (/^\d+\.\s+/.test(line)) {
      if (inUL) {
        html += '</ul>';
        inUL = false;
      }

      if (!inOL) {
        html += '<ol>';
        inOL = true;
      }

      html += `<li>${inlineFormat(
        line.replace(/^\d+\.\s+/, '')
      )}</li>`;

      continue;
    }

    if (!line) {
      closeLists();
      continue;
    }

    closeLists();

    html += `<p>${inlineFormat(line)}</p>`;
  }

  closeLists();

  // Safety fallback if headings were different
  if (!asIsInserted) {
    html += `
      <h2>AS-IS Process Flow</h2>
      <div class="diagram">
        <img src="data:image/png;base64,${asIsBase64}" />
      </div>
    `;
  }

  if (!toBeInserted) {
    html += `
      <h2>TO-BE Process Flow</h2>
      <div class="diagram">
        <img src="data:image/png;base64,${toBeBase64}" />
      </div>
    `;
  }

  return html;
}

const bodyHtml = markdownToHtml(reportContent);

const html = `
