  font-size: 15pt;
  margin-top: 20px;
  margin-bottom: 10px;
}

h3 {
  font-size: 12pt;
  margin-top: 16px;
  margin-bottom: 8px;
}

p {
  margin: 5px 0;
}

table {
  border-collapse: collapse;
  width: 100%;
  margin: 10px 0 16px 0;
  font-size: 8.5pt;
}

th,
